import { Amplify, API } from 'aws-amplify';
import { Auth } from 'aws-amplify';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:3001';

// Log the API URL being used
console.log('Using API URL:', API_URL);

const devConfig = {
    Auth: {
        region: process.env.REACT_APP_AWS_REGION,
        userPoolId: process.env.REACT_APP_USER_POOL_ID,
        userPoolWebClientId: process.env.REACT_APP_USER_POOL_WEB_CLIENT_ID,
        mandatorySignIn: true,
        cookieStorage: {
            domain: 'localhost',
            path: '/',
            expires: 365,
            secure: false
        },
        storage: window.localStorage,
        authenticationFlowType: 'USER_PASSWORD_AUTH'
    },
    API: {
        endpoints: [
            {
                name: 'api',
                endpoint: API_URL,
                region: process.env.REACT_APP_AWS_REGION,
                custom_header: async () => {
                    try {
                        const session = await Auth.currentSession();
                        const token = session.getIdToken().getJwtToken();
                        console.log('Using token for API request:', token.substring(0, 20) + '...');
                        return {
                            'Authorization': `Bearer ${token}`,
                            'Content-Type': 'application/json'
                        };
                    } catch (error) {
                        console.error('Error getting token:', error);
                        return {
                            'Content-Type': 'application/json'
                        };
                    }
                }
            }
        ]
    }
};

// Add API request interceptor for debugging
API.interceptors.request.use(
    (config) => {
        console.log('Making API request to:', config.url);
        console.log('Request headers:', config.headers);
        console.log('Request data:', config.data);
        return config;
    },
    (error) => {
        console.error('API request error:', error);
        return Promise.reject(error);
    }
);

// Add API response interceptor for debugging
API.interceptors.response.use(
    (response) => {
        console.log('API response:', response);
        return response;
    },
    (error) => {
        console.error('API response error:', error);
        if (error.message === 'Network Error') {
            console.error('Network Error Details:', {
                url: error.config?.url,
                method: error.config?.method,
                headers: error.config?.headers,
                baseURL: error.config?.baseURL
            });
        }
        return Promise.reject(error);
    }
);

// Imprimir la configuración para debugging
console.log('API URL:', API_URL);
console.log('Configuración completa:', devConfig);

export default devConfig;
